// Pet safety index — record JAH-GAI-PETTRACKER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"battery_weeks": 3, "gps_accuracy_m": 5, "price_usd": 100};
var value = (m.battery_weeks*100/m.gps_accuracy_m/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAI-PETTRACKER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAI-PETTRACKER-000001|' + value.toFixed(2) + ' safety index');

